"""Calculates the sum of the square differences of the components of
    v1 and v2 vectors.
    """
def sum_of_square_difference(v1: Any, v2: Any) -> object {
    sum = 0.0;
    for (c1, c2) in zip(v1, v2) {
        t = c1 - c2;
        sum += t * t;
    }
    return sum;
}

"""Get gaps merged across channels/streams
    Parameters
    ----------
    gaps: dictionary
        contains channel/gap array pairs

    Returns
    -------
    array_like
        an array of startime/endtime arrays representing gaps.

    Notes
    -----
    Takes an dictionary of gaps, and merges those gaps across channels,
        returning an array of the merged gaps.
    """
def get_merged_gaps(gaps: Any) -> object {
    merged_gaps = [];
    for key in gaps {
        merged_gaps.extend(gaps[key]);
    }
    sorted_gaps = sorted(merged_gaps, key=lambda (gap: Any) { gap[0]; });
    merged_gaps = [];
    merged_gap = None;
    for gap in sorted_gaps {
        if (merged_gap is None) {
            merged_gap = gap;
        } elif (gap[0] > merged_gap[2]) {
            merged_gaps.append(merged_gap);
            merged_gap = gap;
        } elif (gap[0] <= merged_gap[2]) {
            if (gap[1] > merged_gap[1]) {
                merged_gap[1] = gap[1];
                merged_gap[2] = gap[2];
            }
        }
    }
    if (merged_gap is not None) {
        merged_gaps.append(merged_gap);
    }
    return merged_gaps;
}
